import re
import threading
from collections.abc import Iterator
from pathlib import Path

import pytest

from tests.app.bundle_check import built_by, keychain, pinned, round_trip
from tests.fakes import FakeKeyring

# As `uv export` writes uv.lock's pins, with markers this Python always or never meets.
CONSTRAINTS = """\
# This file was autogenerated by uv via the following command:
#    uv export --locked --no-dev --extra app --group mac-app --no-emit-project
charset-normalizer==3.5.1 \\
    --hash=sha256:01e93745f7f219b703b60ba7afead36cfc4242782be5af484673fc500df12da5
    # via requests
colorama==0.4.6 ; python_version < '3' \\
    --hash=sha256:08695f5cb7ed6e0531a20572697297273c47b8cae5a63ffc6d6ed5c201be6e44
soupsieve==3.0.4 ; python_version >= '3' \\
    --hash=sha256:8412826614f9c632227067d0985aeb9f584bd15efc852955430e097a9fe7afbf
soupsieve==2.10 ; python_version < '3' \\
    --hash=sha256:49e9380d7d2905463583bafe285e818c7366a9ed7b3aee221c1ac79c905d8bc0
"""
BUILD_CONSTRAINTS = """\
# This file was autogenerated by uv via the following command:
#    uv export --locked --only-group build-backend --no-emit-project
uv-build==0.9.30 \\
    --hash=sha256:015cab944b4c4437549c4ad11ad65c37aed6a6eb390e326d8f81945acc423533 \\
    --hash=sha256:14ac36cb0ccdc7a847e3d41903eb5d0091db4f5efcd34e693da82d6484fc5539
"""
# What CONSTRAINTS pins here, and the project.
LOCKED = {"r3context": "0.6.10", "Charset_Normalizer": "3.5.1", "soupsieve": "3.0.4"}


def app_packages(
    tmp_path: Path, versions: dict[str, str], generator: str = "uv 0.9.30"
) -> Path:
    """An app_packages folder that holds each distribution at its version, each built
    by ``generator``."""
    packages = tmp_path / "app_packages"
    for name, version in versions.items():
        dist_info = packages / f"{name}-{version}.dist-info"
        dist_info.mkdir(parents=True)
        metadata = f"Metadata-Version: 2.1\nName: {name}\nVersion: {version}\n"
        (dist_info / "METADATA").write_text(metadata, encoding="utf-8")
        wheel = f"Wheel-Version: 1.0\nGenerator: {generator}\n"
        (dist_info / "WHEEL").write_text(wheel, encoding="utf-8")
    return packages


@pytest.fixture
def constraints(tmp_path: Path) -> Path:
    path = tmp_path / "constraints.txt"
    path.write_text(CONSTRAINTS, encoding="utf-8")
    return path


@pytest.fixture
def build_constraints(tmp_path: Path) -> Path:
    path = tmp_path / "build-constraints.txt"
    path.write_text(BUILD_CONSTRAINTS, encoding="utf-8")
    return path


def test_pinned_counts_the_locked_packages_at_their_versions(
    tmp_path: Path, constraints: Path
) -> None:
    assert pinned(app_packages(tmp_path, LOCKED), constraints) == 2


@pytest.mark.parametrize(
    ("changed", "problem"),
    [
        (
            {"Charset_Normalizer": "3.6.0"},
            "charset-normalizer 3.6.0: uv.lock pins ==3.5.1",
        ),
        ({"soupsieve": "2.10"}, "soupsieve 2.10: uv.lock pins ==3.0.4"),
        ({"colorama": "0.4.6"}, "colorama 0.4.6: uv.lock pins no version"),
        ({"zipp": "4.1.0"}, "zipp 4.1.0: uv.lock pins no version"),
    ],
    ids=["another version", "the other python's", "pinned only elsewhere", "unlocked"],
)
def test_pinned_exits_on_a_package_at_a_version_uv_lock_does_not_pin_here(
    tmp_path: Path, constraints: Path, changed: dict[str, str], problem: str
) -> None:
    packages = app_packages(tmp_path, LOCKED | changed)
    with pytest.raises(SystemExit, match=re.escape(problem)):
        pinned(packages, constraints)


def test_pinned_exits_on_a_locked_package_the_bundle_lacks(
    tmp_path: Path, constraints: Path
) -> None:
    packages = app_packages(tmp_path, {"r3context": "0.6.10", "soupsieve": "3.0.4"})
    problem = "charset-normalizer: uv.lock pins ==3.5.1, but it is missing"
    with pytest.raises(SystemExit, match=re.escape(problem)):
        pinned(packages, constraints)


def test_built_by_names_the_locked_backend(
    tmp_path: Path, build_constraints: Path
) -> None:
    packages = app_packages(tmp_path, {"r3context": "0.6.10"})
    assert built_by(packages, build_constraints) == "uv 0.9.30"


def test_built_by_exits_on_another_backend_version(
    tmp_path: Path, build_constraints: Path
) -> None:
    packages = app_packages(tmp_path, {"r3context": "0.6.10"}, generator="uv 0.9.31")
    problem = "r3context was built by uv 0.9.31, but uv.lock pins uv-build ==0.9.30"
    with pytest.raises(SystemExit, match=re.escape(problem)):
        built_by(packages, build_constraints)


class StalledKeyring(FakeKeyring):
    """A store whose saves wait until ``answer`` is set, as one showing a dialog does."""

    def __init__(self) -> None:
        super().__init__()
        self.answer = threading.Event()

    def set_password(self, service: str, username: str, password: str) -> None:
        self.answer.wait()
        super().set_password(service, username, password)


class ForgetfulKeyring(FakeKeyring):
    """A store that keeps what it is given but never reads it back."""

    def get_password(self, service: str, username: str) -> str | None:
        return None


@pytest.fixture
def stalled() -> Iterator[StalledKeyring]:
    store = StalledKeyring()
    yield store
    store.answer.set()


def test_keychain_exits_on_a_store_that_is_not_the_macos_keychain():
    with pytest.raises(SystemExit, match="finds FakeKeyring, not the macOS Keychain"):
        keychain()


def test_round_trip_saves_reads_back_and_deletes_a_throwaway_item():
    store = FakeKeyring()
    round_trip(store)
    assert store.passwords == {}


def test_round_trip_exits_on_an_item_that_does_not_read_back():
    with pytest.raises(SystemExit, match="was not saved, read back as saved"):
        round_trip(ForgetfulKeyring())


def test_round_trip_gives_up_on_a_store_that_does_not_answer(
    stalled: StalledKeyring, monkeypatch: pytest.MonkeyPatch
):
    monkeypatch.setattr("tests.app.bundle_check.KEYCHAIN_SECONDS", 0.1)
    with pytest.raises(SystemExit, match="did not answer within 0.1 s"):
        round_trip(stalled)
